// W27 - style parity between two workbooks (any mix of .xls/.xlsx) read by Apache POI: per cell font(name,size,bold,italic,underline,rgb), fill(pattern,rgb), borders(style x4), numfmt, alignment(h,v,wrap),
// plus merges, hidden columns, column widths, row heights. usage: W27 <expected> <actual> [sheet ...]  ; prints per-attribute mismatch counts and the first examples. INCONCLUSIVE if 0 cells compared.
import java.io.*; import java.util.*; import org.apache.poi.ss.usermodel.*; import org.apache.poi.hssf.usermodel.*; import org.apache.poi.xssf.usermodel.*; import org.apache.poi.hssf.util.HSSFColor;
public class W27_StyleParity {
 static String rgb(Workbook w, Color c){ if(c==null) return "-"; if(c instanceof XSSFColor){ byte[] b=((XSSFColor)c).getRGB(); return b==null?"-":String.format("%02X%02X%02X",b[0]&255,b[1]&255,b[2]&255);} if(c instanceof HSSFColor){ short[] t=((HSSFColor)c).getTriplet(); return String.format("%02X%02X%02X",t[0],t[1],t[2]);} return "-"; }
 static Map<String,String> st(Workbook w, Cell c){ CellStyle s=c.getCellStyle(); Font f=w.getFontAt(s.getFontIndex()); Map<String,String> m=new LinkedHashMap<>();
  m.put("font",f.getFontName()+"/"+f.getFontHeightInPoints()+"/b"+f.getBold()+"/i"+f.getItalic()+"/u"+f.getUnderline()); Color fc=(f instanceof XSSFFont)?((XSSFFont)f).getXSSFColor():(f instanceof HSSFFont? ((HSSFWorkbook)w).getCustomPalette().getColor(((HSSFFont)f).getColor()):null); m.put("fontColor",rgb(w,fc));
  boolean fill=s.getFillPattern()!=FillPatternType.NO_FILL; m.put("fill",fill? s.getFillPattern()+"/"+rgb(w,s.getFillForegroundColorColor()):"none");
  m.put("border",s.getBorderTop()+","+s.getBorderBottom()+","+s.getBorderLeft()+","+s.getBorderRight()); m.put("numfmt",s.getDataFormatString().replace("\\(","(").replace("\\)",")").replace("\\-","-")); /* formats compared modulo escaped literal parentheses (renders identically) */ m.put("align",s.getAlignment()+"/"+s.getVerticalAlignment()+"/"+s.getWrapText()); return m; }
 public static void main(String[] a) throws Exception { Workbook e=WorkbookFactory.create(new FileInputStream(a[0])), x=WorkbookFactory.create(new FileInputStream(a[1])); Map<String,Integer> bad=new TreeMap<>(); List<String> ex=new ArrayList<>(); int cells=0;
  Set<String> only=new HashSet<>(Arrays.asList(a).subList(2,a.length));
  for(int i=0;i<e.getNumberOfSheets();i++){ Sheet se=e.getSheetAt(i); if(!only.isEmpty()&&!only.contains(se.getSheetName())) continue; Sheet sx=x.getSheet(se.getSheetName()); if(sx==null){ bad.merge("sheetMissing",1,Integer::sum); continue; }
   if(se.getNumMergedRegions()!=sx.getNumMergedRegions()) bad.merge("mergedCount",1,Integer::sum);
   int maxc=0; for(Row r:se) if(r.getLastCellNum()>maxc) maxc=r.getLastCellNum();
   for(int c=0;c<=maxc;c++){ if(se.isColumnHidden(c)!=sx.isColumnHidden(c)) bad.merge("hiddenCol",1,Integer::sum); if(se.getColumnWidth(c)!=sx.getColumnWidth(c)) { bad.merge("colWidth",1,Integer::sum); if(ex.size()<4) ex.add(se.getSheetName()+" col"+c+" w "+se.getColumnWidth(c)+" vs "+sx.getColumnWidth(c)); } }
   for(Row r:se){ Row rx=sx.getRow(r.getRowNum()); if(rx==null){ boolean allDefault=true; for(Cell cc:r){ CellStyle q=cc.getCellStyle(); if(cc.getCellType()!=CellType.BLANK||q.getFillPattern()!=FillPatternType.NO_FILL||q.getBorderTop()!=BorderStyle.NONE||q.getBorderBottom()!=BorderStyle.NONE||q.getBorderLeft()!=BorderStyle.NONE||q.getBorderRight()!=BorderStyle.NONE){ allDefault=false; break; } } if(!allDefault) bad.merge("rowMissing",1,Integer::sum); continue; } if(r.getHeight()!=rx.getHeight()) bad.merge("rowHeight",1,Integer::sum);
    for(Cell c:r){ Cell cx=rx.getCell(c.getColumnIndex()); if(cx==null){ if(c.getCellType()==CellType.BLANK && c.getCellStyle().getFillPattern()==FillPatternType.NO_FILL && c.getCellStyle().getBorderTop()==BorderStyle.NONE && c.getCellStyle().getBorderBottom()==BorderStyle.NONE && c.getCellStyle().getBorderLeft()==BorderStyle.NONE && c.getCellStyle().getBorderRight()==BorderStyle.NONE && c.getCellStyle().getDataFormatString().equals("General")) continue; bad.merge("cellMissing",1,Integer::sum); continue; } cells++; Map<String,String> m1=st(e,c), m2=st(x,cx);
     for(String k:m1.keySet()) if(!m1.get(k).equals(m2.get(k))){ bad.merge(k,1,Integer::sum); if(ex.size()<8 && (System.getenv("ONLY")==null||System.getenv("ONLY").equals(k))) ex.add(se.getSheetName()+"!"+c.getAddress()+" "+k+" "+m1.get(k)+" | "+m2.get(k)); } } } }
  System.out.println("§STYLE_PARITY cells="+cells+" mismatches="+bad+(cells==0?" INCONCLUSIVE":""));
  for(String s:ex) System.out.println("   "+s); System.out.println("§STYLE_PARITY_VERDICT "+(cells==0?"INCONCLUSIVE":(bad.isEmpty()?"PASS":"FAIL"))); }}
